dateOf.src:
function dateOf(day) {
  const [y, m, d] = START_DATE.split('-').map(Number), t = new Date(Date.UTC(y, m - 1, d + day - 1));
  return { iso: `${t.getUTCFullYear()}-${pad2(t.getUTCMonth() + 1)}-${pad2(t.getUTCDate())}`, y: t.getUTCFullYear(), m: t.getUTCMonth() + 1, d: t.getUTCDate(), wd: t.getUTCDay() };
}

dayOfYear.src:
function dayOfYear(day) {
  const t = dateOf(day);
  return Math.round((Date.UTC(t.y, t.m - 1, t.d) - Date.UTC(t.y, 0, 1)) / 86400000) + 1;
}

foLineCheckReady.src:
function foLineCheckReady(fo) {
  if (!fo || fo.done) return false;
  if (!(fo.sectors >= 12 && fo.blockMin >= 900)) return false;
  if (fo.lineCheck === 'fail' && Number.isInteger(fo.failSectors)) return fo.sectors >= fo.failSectors + 4;
  return true;
}

