function surfaceWindOf(metar) {
  const m = /(\d{3})(\d{2,3})(?:G\d{2,3})?KT/.exec(String(metar || ''));
  if (!m) return { from: 360, kt: 0 };
  return { from: +m[1] || 360, kt: +m[2] };
}

